class Solution {
public:
    string convertText(string s) {
        bool start = true;
        for (char &c : s) {
            if (c == ' ' || c == '-') { start = true; continue; }
            if (!isalpha((unsigned char)c)) { continue; }
            c = start ? toupper(c) : tolower(c);
            start = false;
        }
        return s;
    }
};

