class Solution {
    public String convertText(String s) {
        char[] a = s.toCharArray();
        boolean start = true;
        for (int i = 0; i < a.length; i++) {
            char c = a[i];
            if (c == ' ' || c == '-') { start = true; continue; }
            if (!Character.isLetter(c)) continue;
            a[i] = start ? Character.toUpperCase(c) : Character.toLowerCase(c);
            start = false;
        }
        return new String(a);
    }
}

