class Solution:
    def convertText(self, content_text: str) -> str:
        out = []
        start = True
        for c in content_text:
            if c in ' -':
                start = True
                out.append(c)
            elif c.isalpha():
                out.append(c.upper() if start else c.lower())
                start = False
            else:
                out.append(c)
        return ''.join(out)

