class Solution {
public:
    string convertText(string s) {
        string out;
        out.reserve(s.size());
        bool start = true;
        for (char c : s) {
            if (c == ' ' || c == '-') { start = true; out += c; }
            else if (isalpha((unsigned char)c)) {
                out += start ? toupper(c) : tolower(c);
                start = false;
            } else out += c;
        }
        return out;
    }
};

