var convertText = function(s) {
    const arr = [];
    let start = true;
    for (const c of s) {
        if (c === ' ' || c === '-') { start = true; arr.push(c); }
        else if (/[a-zA-Z]/.test(c)) { arr.push(start ? c.toUpperCase() : c.toLowerCase()); start = false; }
        else arr.push(c);
    }
    return arr.join('');
};

